def is_woodall(n):
    def is_prime(num):
        if num <= 1:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    def woodall_number(k):
        return k * (2 ** k) - 1

    k = 1
    while True:
        wn = woodall_number(k)
        if wn == n:
            return True
        elif wn > n:
            return False
        k += 1

