def sequence(n):
    if n < 1:
        return None
    elif n == 1:
        return 1
    elif n == 2:
        return 1
    elif n == 3:
        return 2

    seq = [0] * (n + 1)
    seq[1], seq[2], seq[3] = 1, 1, 2

    for i in range(4, n + 1):
        seq[i] = seq[seq[i - 1]] + seq[i - seq[i - 1]]

    return seq[n]

assert sequence(10) == 6
```

