def eulerian_num(n, m):
    A = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        A[i][0] = 1 if i == 0 else 0
    for i in range(1, n + 1):
        for j in range(1, min(i, m + 1)):
            A[i][j] = (i - j) * A[i - 1][j] + (j + 1) * A[i - 1][j - 1]
    return A[n][m]

assert eulerian_num(3, 1) == 4
