def pancake_sort(arr):
    def flip(sub_arr, k):
        return sub_arr[:k][::-1] + sub_arr[k:]

    def find_max_index(sub_arr):
        return sub_arr.index(max(sub_arr))

    n = len(arr)
    for curr_size in range(n, 1, -1):
        max_index = find_max_index(arr[:curr_size])

        if max_index != curr_size - 1:
            if max_index != 0:
                arr = flip(arr, max_index + 1)
            arr = flip(arr, curr_size)

    return arr

# Example usage
assert pancake_sort([15, 79, 25, 38, 69]) == [15, 25, 38, 69, 79]
