def max_sum(arr):
    n = len(arr)
    if n == 0:
        return 0

    # Initialize the maximum sum increasing subsequence (MSIS) arrays
    inc = [0] * n
    dec = [0] * n

    # Fill the inc array
    for i in range(n):
        inc[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i] and inc[i] < inc[j] + arr[i]:
                inc[i] = inc[j] + arr[i]

    # Fill the dec array
    for i in range(n - 1, -1, -1):
        dec[i] = arr[i]
        for j in range(n - 1, i, -1):
            if arr[j] < arr[i] and dec[i] < dec[j] + arr[i]:
                dec[i] = dec[j] + arr[i]

    # Calculate the maximum sum of bitonic subsequence
    max_bitonic_sum = 0
    for i in range(n):
        max_bitonic_sum = max(max_bitonic_sum, inc[i] + dec[i] - arr[i])

    return max_bitonic_sum

