def newman_prime(n):
    if n < 1:
        return None

    primes = []
    candidate = 2

    while len(primes) < n:
        is_prime = True
        for p in primes:
            if p * p > candidate:
                break
            if candidate % p == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(candidate)
            if len(primes) > 1:
                newman_shanks_williams = primes[-1] + primes[-2] + 1
                if newman_shanks_williams not in primes:
                    primes.append(newman_shanks_williams)
        candidate += 1

    return primes[n - 1]

assert newman_prime(3) == 7
