def max_sub_array_sum_repeated(arr, n, k):
    def kadane(array):
        max_current = max_global = array[0]
        for i in range(1, len(array)):
            max_current = max(array[i], max_current + array[i])
            if max_current > max_global:
                max_global = max_current
        return max_global

    if k == 0:
        return 0

    max_kadane = kadane(arr)

    total_sum = sum(arr)
    max_suffix = float('-inf')
    current_suffix = 0
    for i in range(n - 1, -1, -1):
        current_suffix += arr[i]
        max_suffix = max(max_suffix, current_suffix)

    max_prefix = float('-inf')
    current_prefix = 0
    for i in range(n):
        current_prefix += arr[i]
        max_prefix = max(max_prefix, current_prefix)

    if total_sum > 0:
        return max(max_kadane, max_suffix + max_prefix + total_sum * (k - 2))
    else:
        return max(max_kadane, max_suffix + max_prefix)

# Test the function
assert max_sub_array_sum_repeated([10, 20, -30, -1], 4, 3) == 30
