def max_sub_array_sum_repeated(arr, k, n):
    def max_sub_array_sum(arr):
        max_ending_here = max_so_far = arr[0]
        for x in arr[1:]:
            max_ending_here = max(x, max_ending_here + x)
            max_so_far = max(max_so_far, max_ending_here)
        return max_so_far

    if k == 1:
        return max_sub_array_sum(arr)

    max_sum_single = max_sub_array_sum(arr)
    total_sum = sum(arr)

    # Calculate prefix and suffix sums
    prefix_sum = float('-inf')
    current_sum = 0
    for num in arr:
        current_sum += num
        prefix_sum = max(prefix_sum, current_sum)

    suffix_sum = float('-inf')
    current_sum = 0
    for num in reversed(arr):
        current_sum += num
        suffix_sum = max(suffix_sum, current_sum)

    if total_sum > 0:
        return max(max_sum_single, prefix_sum + suffix_sum + (k - 2) * total_sum)
    else:
        return max(max_sum_single, prefix_sum + suffix_sum)

