def max_sum_increasing_subseq(arr, n, i, k):
    # Calculate the maximum sum of increasing subsequence up to index i
    max_sum = [0] * n
    for j in range(i + 1):
        max_sum[j] = arr[j]
        for l in range(j):
            if arr[j] > arr[l]:
                max_sum[j] = max(max_sum[j], max_sum[l] + arr[j])

    # Add the kth element to the sum if it can form an increasing subsequence
    max_sum_with_k = 0
    for j in range(i + 1):
        if arr[i] < arr[k]:
            max_sum_with_k = max(max_sum_with_k, max_sum[j] + arr[k])

    return max(max_sum) if max_sum_with_k == 0 else max(max_sum_with_k, max(max_sum))

